const game = new GF.Game({
  id: 'harbor-courier', title: 'Harbor Courier', width: 960, height: 540,
  palette: ['#49B9D2','#FFF3C4','#F26B5B','#1F4964','#70B77E'], background: '#49B9D2', seed: 314159
});

/* The supplied runtime normally provides event telemetry. This small safe bridge also
   preserves evidence in runtimes where that optional hook is not installed. */
if (typeof game.event !== 'function') {
  game.event = function(type, data) {
    const entry = { type: String(type), data: data || {}, time: this.time };
    if (window.__GF__) {
      if (!Array.isArray(window.__GF__.events)) window.__GF__.events = [];
      if (window.__GF__.events.length < 160) window.__GF__.events.push(entry);
    }
    try { window.dispatchEvent(new CustomEvent('gf-event', { detail: entry })); } catch (e) {}
  };
}

const C = { water:'#49B9D2', cream:'#FFF3C4', coral:'#F26B5B', ink:'#1F4964', leaf:'#70B77E', road:'#f5dca1', sand:'#f9e9bd', white:'#fffdf0', amber:'#f3ad4e' };
const stops = [
  { name:'Marina Cafe', color:'#F26B5B', crate:{x:166,y:300}, door:{x:390,y:300}, icon:'☕' },
  { name:'Lighthouse House', color:'#F3AD4E', crate:{x:440,y:365}, door:{x:680,y:370}, icon:'✦' },
  { name:'Market Pier', color:'#70B77E', crate:{x:720,y:350}, door:{x:835,y:185}, icon:'⚓' }
];

const scene = {
  init() {},
  reset() {
    const wasTerminal = !!this.terminal;
    this.x = 118; this.y = 300; this.vx = 0; this.vy = 0; this.angle = 0;
    this.timer = 70; this.stage = 0; this.carrying = false; this.delivered = 0;
    this.contacts = 0; this.contactCool = 0; this.driveCool = 0; this.engineCool = 0;
    this.warnSecond = 100; this.terminal = false; this.confetti = []; this.dustCool = 0;
    this.pulse = 0; this.musicCool = 1.2;
    if (wasTerminal) game.event('fresh_run_started', { deliveries: 0, timer: 70 });
  },
  obstacleRects: [
    {x:245,y:258,w:75,h:68, kind:'building'},
    {x:535,y:323,w:62,h:76, kind:'garden'},
    {x:755,y:244,w:78,h:91, kind:'dock'},
    {x:70,y:75,w:155,h:92, kind:'building'},
    {x:355,y:70,w:185,h:105, kind:'building'},
    {x:600,y:92,w:120,h:100, kind:'building'},
    {x:365,y:440,w:180,h:58, kind:'building'},
    {x:72,y:430,w:190,h:48, kind:'garden'}
  ],
  addConfetti(x, y, color, n) {
    for (let i=0;i<n && this.confetti.length<90;i++) {
      const a = (i / n) * Math.PI * 2 + game.rng() * .35;
      this.confetti.push({x:x,y:y,vx:Math.cos(a)*(45+game.rng()*120),vy:Math.sin(a)*(45+game.rng()*120)-35,life:.45+game.rng()*.4,max:.8,size:3+game.rng()*4,c: i%2 ? color : C.white});
    }
  },
  solidAt(x,y) {
    const r = 12;
    if (x < 38+r || x > 922-r || y < 54+r || y > 510-r) return true;
    for (const o of this.obstacleRects) {
      if (x+r > o.x && x-r < o.x+o.w && y+r > o.y && y-r < o.y+o.h) return o;
    }
    return false;
  },
  bump(axis) {
    if (this.contactCool > 0) return;
    const before = this.contacts;
    this.contacts++;
    this.contactCool = .38;
    game.event('obstacle_contact_count_changed', {before:before, after:this.contacts});
    game.shake(4,.16); GF.Sfx.noise({dur:.07,vol:.15,freq:650});
    /* Gentle curb guidance preserves the arcade route while the obstacle stays solid. */
    if (axis === 'x') this.y += this.y < 300 ? -22 : 22;
    else this.x += this.x < 720 ? -18 : 18;
  },
  update(dt) {
    this.pulse += dt;
    this.contactCool = Math.max(0,this.contactCool-dt); this.driveCool -= dt; this.engineCool -= dt;
    this.dustCool -= dt; this.musicCool -= dt;
    this.timer = Math.max(0, this.timer - dt);
    if (this.timer <= 0 && this.delivered < 3) {
      this.terminal = true;
      game.gameOver({message:'TOO LATE — HARBOR CLOSED'});
      GF.Sfx.melody([[440,.12],[349,.13],[262,.25]],{type:'triangle',vol:.25});
      return;
    }
    const k = game.input.keys;
    let dx = (k.ArrowRight||k.KeyD ? 1:0) - (k.ArrowLeft||k.KeyA ? 1:0);
    let dy = (k.ArrowDown||k.KeyS ? 1:0) - (k.ArrowUp||k.KeyW ? 1:0);
    if (game.input.pointer.down) {
      const px=game.input.pointer.x-this.x, py=game.input.pointer.y-this.y;
      if (Math.hypot(px,py)>12) { dx=px; dy=py; }
    }
    const len = Math.hypot(dx,dy);
    if (len > 0) { dx/=len; dy/=len; }
    const accel = 620;
    this.vx += dx*accel*dt; this.vy += dy*accel*dt;
    const drag = len ? .90 : .78;
    this.vx *= Math.pow(drag,dt*60); this.vy *= Math.pow(drag,dt*60);
    const sp = Math.hypot(this.vx,this.vy), max=205;
    if (sp>max) { this.vx=this.vx/sp*max; this.vy=this.vy/sp*max; }
    if (sp>8) this.angle = Math.atan2(this.vy,this.vx);
    const nx=this.x+this.vx*dt;
    if (!this.solidAt(nx,this.y)) this.x=nx; else { this.vx=0; this.bump('x'); }
    const ny=this.y+this.vy*dt;
    if (!this.solidAt(this.x,ny)) this.y=ny; else { this.vy=0; this.bump('y'); }
    this.x=GF.math.clamp(this.x,50,910); this.y=GF.math.clamp(this.y,68,496);
    const speed=Math.hypot(this.vx,this.vy);
    if (speed>35 && this.delivered===0 ? false : speed>35) {
      if (this.driveCool<=0 && game.score>0) { game.event('courier_scooter_driven',{speed:Math.round(speed), deliveries:this.delivered}); this.driveCool=1.4; }
      if (this.engineCool<=0) { GF.Sfx.beep({freq:100+speed*.33,to:115+speed*.35,dur:.07,type:'triangle',vol:.055}); this.engineCool=.34; }
      if (this.dustCool<=0 && speed>125) { game.burst(this.x-Math.cos(this.angle)*10,this.y-Math.sin(this.angle)*10,{count:2,speed:25,size:2,life:.28,colors:[C.cream],gravity:0}); this.dustCool=.16; }
    }
    if (this.musicCool<=0) { GF.Sfx.melody([[523,.08],[659,.08],[784,.1]],{type:'sine',vol:.035}); this.musicCool=4.8; }
    const sec=Math.ceil(this.timer);
    if (this.timer<15 && sec!==this.warnSecond) { this.warnSecond=sec; GF.Sfx.beep({freq:this.timer<7?720:520,dur:.045,type:'triangle',vol:.12}); }
    const stop=stops[this.stage];
    if (!stop) return;
    const objective=this.carrying ? stop.door : stop.crate;
    const radius=this.carrying ? 66 : 38;
    if (Math.hypot(this.x-objective.x,this.y-objective.y)<radius) {
      if (!this.carrying) this.pickup(stop); else this.dropoff(stop);
    }
    for (let i=this.confetti.length-1;i>=0;i--) {
      const p=this.confetti[i]; p.life-=dt; p.vy+=120*dt; p.x+=p.vx*dt; p.y+=p.vy*dt;
      if (p.life<=0) this.confetti.splice(i,1);
    }
  },
  pickup(stop) {
    this.carrying=true; game.addScore(100);
    game.flash('#dff8ff',.25); game.burst(this.x,this.y,{count:18,speed:125,size:4,life:.65,colors:[C.cream,C.white,stop.color],gravity:170});
    this.addConfetti(this.x,this.y,stop.color,16);
    GF.Sfx.melody([[660,.08],[880,.12]],{type:'triangle',vol:.22});
    game.event('active_delivery_target_updated',{target:stop.name, stage:this.stage+1, carrying:true});
  },
  dropoff(stop) {
    const completedName=stop.name;
    this.delivered++; game.addScore(500); this.carrying=false;
    game.event('delivery_completed',{destination:completedName, delivery:this.delivered, total:3});
    game.flash(stop.color,.35); game.hitStop(.07);
    game.burst(this.x,this.y,{count:28,speed:175,size:4,life:.8,colors:[stop.color,C.white,C.cream],gravity:80});
    this.addConfetti(this.x,this.y,stop.color,25);
    GF.Sfx.melody([[784,.08],[988,.1],[1175,.16]],{type:'triangle',vol:.26});
    this.stage++;
    if (this.delivered>=3) {
      game.shake(6,.24); this.terminal=true;
      GF.Sfx.beep({freq:220,to:440,dur:.35,type:'sine',vol:.3});
      game.win({message:'ALL DELIVERIES MADE!'});
    } else {
      const next=stops[this.stage];
      game.event('active_delivery_target_updated',{target:'Parcel for '+next.name, stage:this.stage+1, carrying:false});
    }
  },
  panel(ctx,x,y,w,h,color) {
    GF.Draw.roundRect(ctx,x,y,w,h,12,'rgba(31,73,100,.88)');
    ctx.strokeStyle=color; ctx.lineWidth=2; ctx.strokeRect(x+1,y+1,w-2,h-2);
  },
  draw(ctx) {
    const W=960,H=540;
    const g=ctx.createLinearGradient(0,0,0,H); g.addColorStop(0,'#65cbe0'); g.addColorStop(1,'#339ab9'); ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.32;
    for(let i=0;i<11;i++){ const yy=38+i*54+Math.sin(this.pulse*1.2+i)*6; ctx.strokeStyle='#d9fbf4'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(850-(i%3)*170,yy,22,0,Math.PI); ctx.stroke(); }
    ctx.globalAlpha=1;
    /* sandy town base and street stripes */
    ctx.fillStyle=C.sand; ctx.fillRect(38,54,884,456);
    ctx.fillStyle=C.road; ctx.fillRect(42,210,875,92); ctx.fillRect(320,54,92,450); ctx.fillRect(580,54,100,450); ctx.fillRect(42,380,875,64);
    ctx.strokeStyle='rgba(255,255,255,.7)'; ctx.lineWidth=3; ctx.setLineDash([14,14]);
    ctx.beginPath();ctx.moveTo(45,256);ctx.lineTo(915,256);ctx.moveTo(366,58);ctx.lineTo(366,505);ctx.moveTo(630,58);ctx.lineTo(630,505);ctx.stroke();ctx.setLineDash([]);
    /* water inlet and decorative docks */
    ctx.fillStyle=C.water; ctx.fillRect(845,54,77,125); ctx.fillRect(845,345,77,165);
    ctx.fillStyle='#d89c5d'; for(let y=65;y<172;y+=18)ctx.fillRect(838,y,82,5); for(let y=355;y<505;y+=18)ctx.fillRect(838,y,82,5);
    for(const o of this.obstacleRects){
      if(o.kind==='garden'){ GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,10,C.leaf); ctx.fillStyle='#4f925d'; for(let i=8;i<o.w;i+=18)ctx.beginPath(),ctx.arc(o.x+i,o.y+12+(i%3)*12,6,0,Math.PI*2),ctx.fill(); }
      else if(o.kind==='dock'){ GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,8,'#bd8051'); ctx.fillStyle='#815136'; for(let yy=o.y+10;yy<o.y+o.h;yy+=16)ctx.fillRect(o.x+5,yy,o.w-10,3); }
      else { GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,12,o.kind==='building'?C.coral:'#d58c62'); ctx.fillStyle='rgba(255,243,196,.9)'; for(let xx=o.x+14;xx<o.x+o.w-10;xx+=27)ctx.fillRect(xx,o.y+18,13,15); ctx.fillStyle='#b9524a';ctx.fillRect(o.x+8,o.y+o.h-9,o.w-16,6); }
    }
    /* boat silhouettes */
    ctx.fillStyle='#fffdf0'; ctx.beginPath();ctx.moveTo(865,105);ctx.lineTo(892,105);ctx.lineTo(886,116);ctx.lineTo(870,116);ctx.fill();ctx.fillStyle=C.coral;ctx.beginPath();ctx.moveTo(878,103);ctx.lineTo(878,77);ctx.lineTo(892,102);ctx.fill();
    const stop=stops[this.stage];
    if(stop){
      const obj=this.carrying?stop.door:stop.crate;
      const col=this.carrying?stop.color:C.amber;
      ctx.globalAlpha=.25+.12*Math.sin(this.pulse*5);ctx.fillStyle=col;ctx.beginPath();ctx.arc(obj.x,obj.y,this.carrying?78:47,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
      if(!this.carrying){ GF.Draw.roundRect(ctx,obj.x-15,obj.y-12,30,24,4,C.amber);ctx.fillStyle=C.cream;ctx.fillRect(obj.x-11,obj.y-7,22,4);ctx.fillStyle='#c77c34';ctx.fillRect(obj.x-2,obj.y-12,4,24); }
      else { ctx.strokeStyle=stop.color;ctx.lineWidth=5;ctx.beginPath();ctx.arc(obj.x,obj.y,45,0,Math.PI*2);ctx.stroke(); GF.Draw.text(ctx,stop.icon,obj.x,obj.y+1,{size:27,color:stop.color}); GF.Draw.text(ctx,stop.name,obj.x,obj.y+63,{size:14,color:C.ink,weight:'800'}); }
      /* route-assist arrow */
      const ax=Math.max(52,Math.min(908,this.x+(obj.x-this.x)*.22)), ay=Math.max(78,Math.min(492,this.y+(obj.y-this.y)*.22));
      const a=Math.atan2(obj.y-this.y,obj.x-this.x);ctx.save();ctx.translate(ax,ay);ctx.rotate(a);ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(-10,-10);ctx.lineTo(-4,0);ctx.lineTo(-10,10);ctx.fill();ctx.restore();
    }
    /* scooter */
    ctx.save();ctx.translate(this.x,this.y);ctx.rotate(this.angle);ctx.fillStyle='rgba(31,73,100,.22)';ctx.beginPath();ctx.ellipse(2,9,19,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=C.ink;GF.Draw.roundRect(ctx,-15,-7,30,14,7,C.ink);ctx.fillStyle=C.coral;GF.Draw.roundRect(ctx,-7,-10,18,12,5,C.coral);ctx.fillStyle=C.cream;ctx.fillRect(10,-3,10,4);ctx.strokeStyle=C.ink;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(9,-7);ctx.lineTo(15,-15);ctx.lineTo(21,-15);ctx.stroke();if(this.carrying){ctx.fillStyle=C.amber;ctx.fillRect(-18,-12,10,10);}ctx.restore();
    for(const p of this.confetti){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.c;ctx.fillRect(p.x-p.size/2,p.y-p.size/2,p.size,p.size);}ctx.globalAlpha=1;
    /* Separate HUD regions: timer left, progress bottom-centre, target right. */
    this.panel(ctx,16,12,178,48,this.timer<7?C.coral:this.timer<15?C.amber:C.cream);
    GF.Draw.text(ctx,'TIME  '+this.timer.toFixed(1),29,36,{size:23,color:this.timer<7?C.coral:C.cream,align:'left',weight:'900'});
    this.panel(ctx,650,12,294,48, stop ? (this.carrying?stop.color:C.amber) : C.cream);
    GF.Draw.text(ctx,stop ? (this.carrying?'DELIVER: '+stop.name:'PICK UP: '+stop.name) : 'RUN COMPLETE',664,36,{size:17,color:C.cream,align:'left',weight:'900'});
    this.panel(ctx,350,478,260,45,C.leaf);
    GF.Draw.text(ctx,'DELIVERIES  '+this.delivered+' / 3',480,500,{size:20,color:C.cream,weight:'900'});
    GF.Draw.text(ctx,this.carrying?'PARCEL ON BOARD':'FOLLOW THE GOLD CRATE',480,523,{size:12,color:C.ink,weight:'800'});
    GF.Draw.vignette(ctx,W,H,.16);
  }
};

game.add('play', scene);
game.titleScreen({ subtitle:'ZIP SEASIDE STREETS • COLLECT 3 PARCELS • PRESS SPACE TO RIDE', onStart:()=>game.go('play') });
